define('taoQtiItem/qtiCreator/widgets/interactions/helpers/resourceManager',['jquery', 'lodash', 'i18n', 'util/image', 'ui/resourcemgr'], function ($, _, __, imageUtil) {
  'use strict';

  var ns = 'upload';
  return function ($element, options) {
    $element.resourcemgr({
      title: options.title,
      appendContainer: options.mediaManager.appendContainer,
      mediaSourcesUrl: options.mediaManager.mediaSourcesUrl,
      browseUrl: options.mediaManager.browseUrl,
      uploadUrl: options.mediaManager.uploadUrl,
      deleteUrl: options.mediaManager.deleteUrl,
      downloadUrl: options.mediaManager.downloadUrl,
      fileExistsUrl: options.mediaManager.fileExistsUrl,
      params: {
        uri: options.uri,
        lang: options.lang,
        filters: 'image/jpeg,image/png,image/gif,image/svg+xml'
      },
      pathParam: 'path',
      select: function select(e, files) {
        var selected;
        if (files.length > 0) {
          selected = files[0];
          imageUtil.getSize(options.baseUrl + encodeURIComponent(files[0].file), function (size) {
            $element.trigger('selected.' + ns, {
              selected: selected,
              size: size
            });
          });
        }
      }
    });
  };
});
