define('taoQtiItem/qtiCreator/editor/ckEditor/groupToggler',['lodash', 'core/eventifier'], function (_, eventifier) {
  'use strict';
  return function groupToggler() {
    var _registry = [];
    return eventifier({
      register: function register($trigger) {
        var self = this,
          id = _.uniqueId('group-toggler-');
        if (!$trigger || !$trigger.length) {
          this.trigger('error', 'trigger does not exist');
          return this;
        }
        if (!$trigger.data('group-toggler-id')) {
          $trigger.data('group-toggler-id', id).on('show.grouptoggler', function () {
            self.trigger('show', id);
          });
          _registry.push({
            id: id,
            dom: $trigger
          });
        }
        return this;
      }
    }).on('show', function (id) {
      _.forEach(_registry, function (element) {
        if (element.id !== id) {
          element.dom.trigger('showanother.grouptoggler', id);
        }
      });
    });
  };
});
