define('taoQtiItem/qtiCreator/editor/styleEditor/fontSizeChanger',['jquery', 'lodash', 'taoQtiItem/qtiCreator/editor/styleEditor/styleEditor'], function ($, _, styleEditor) {
  'use strict';
  var fontSizeChanger = function fontSizeChanger() {
    var $fontSizeChanger = $('#item-editor-font-size-changer'),
      itemSelector = $fontSizeChanger.data('target'),
      figcaptionSelector = "".concat(itemSelector, " figure figcaption"),
      cssVariablesRootSelector = styleEditor.getConfig().cssVariablesRootSelector,
      $item = $(itemSelector),
      $resetBtn = $fontSizeChanger.parents('.reset-group').find('[data-role="font-size-reset"]'),
      $input = $('#item-editor-font-size-text');
    var itemFontSize = parseInt($item.css('font-size'), 10);
    var styleEditorApply = function styleEditorApply(val) {
      var valStr = val ? "".concat(val.toString(), "px") : null;
      var varName = '--styleeditor-font-size';
      styleEditor.apply(cssVariablesRootSelector, varName, valStr);
      styleEditor.apply(itemSelector, 'font-size', valStr ? "var(".concat(varName, ")") : null);
      if (val) {
        var figcaptionSize = val > 14 ? (val - 2).toString() : Math.min(val, 12).toString();
        styleEditor.apply(figcaptionSelector, 'font-size', "".concat(figcaptionSize, "px"));
      } else {
        styleEditor.apply(figcaptionSelector, 'font-size');
      }
    };
    $fontSizeChanger.find('a').on('click', function (e) {
      e.preventDefault();
      if ($(this).data('action') === 'reduce') {
        if (itemFontSize <= 10) {
          return;
        }
        itemFontSize--;
      } else {
        itemFontSize++;
      }
      styleEditorApply(itemFontSize);
      $input.val(itemFontSize);
      $(this).parent().blur();
    });
    $input.on('keydown', function (e) {
      var c = e.keyCode;
      return _.includes([8, 37, 39, 46], c) || c >= 48 && c <= 57 || c >= 96 && c <= 105;
    });
    $input.on('blur', function () {
      if (this.value) {
        itemFontSize = parseInt(this.value, 10);
        styleEditorApply(itemFontSize);
      } else {
        styleEditorApply(null);
      }
    });
    $input.on('keydown', function (e) {
      var c = e.keyCode;
      if (c === 13) {
        $input.trigger('blur');
      }
    });
    $resetBtn.on('click', function () {
      $input.val('');
      styleEditorApply(null);
      itemFontSize = parseInt($item.css('font-size'), 10);
    });
    $(document).on('customcssloaded.styleeditor', function (e, style) {
      var shouldFireStyleChange = false;
      var val = style[cssVariablesRootSelector] && style[cssVariablesRootSelector]['--styleeditor-font-size'];
      if (!val) {
        val = style[itemSelector] && style[itemSelector]['font-size'];
        shouldFireStyleChange = true;
      }
      if (val) {
        itemFontSize = parseInt(val, 10);
        $input.val(itemFontSize);
        if (shouldFireStyleChange) {
          styleEditorApply(itemFontSize);
        }
      } else {
        $input.val();
      }
    });
  };
  return fontSizeChanger;
});
